@using sv_6bcde7277f8c4053ad457a34310a1da3.Services

<div class="message-panel">
    @if (Channel is not null)
    {
        <div class="message-panel-header">
            <h2># @Channel.Name</h2>
            <p>@Channel.Description</p>
        </div>

        <div class="message-list" @onscroll="HandleScroll">
            @if (_isLoadingMore)
            {
                <div class="loading-indicator">Loading older messages…</div>
            }
            @foreach (var message in Messages)
            {
                <MessageItem Message="message"
                             ReplyCount="GetReplyCount(message.Id)"
                             OnReplyClicked="OnReplyClicked"
                             OnReactionAdded="OnReactionAdded" />
            }
        </div>

        <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                      ButtonText="Send"
                      OnMessageSent="OnMessageSent" />
    }
    else
    {
        <div class="no-channel-selected">
            <p>Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter] public Channel? Channel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public EventCallback<int> OnReplyClicked { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReactionAdded { get; set; }
    [Parameter] public EventCallback<string> OnMessageSent { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private bool _isLoadingMore;

    private int GetReplyCount(int messageId)
    {
        var summary = ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId);
        return summary?.ReplyCount ?? 0;
    }

    private async Task HandleScroll()
    {
        // Triggered on scroll; in a real app this would use JS interop to detect scroll-to-top
        // For now we expose the callback for the parent to handle pagination
    }

    public async Task LoadMoreMessages()
    {
        _isLoadingMore = true;
        StateHasChanged();
        await OnLoadMore.InvokeAsync();
        _isLoadingMore = false;
        StateHasChanged();
    }
}

